// Pull yesterday's customers + live bets + leads needing follow-up + open
// visibility targets + top stale tasks + green content ideas + Krish's
// daily_focus history. Powers Marcus's top_three + top_three_alternates +
// top_three_reasoning (synthesis upgrade 2026-05-28).
const SUPA = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1';
// n8n's JS task-runner sandbox doesn't expose this.getCredentials, so the
// service role key is inlined. Rotate via Supabase dashboard if this key
// ever leaks; the workflow only reads + uses it server-side.
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const hdr  = { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}` };
const nowIso = new Date().toISOString();
const yesterdayIso = new Date(Date.now() - 86400000).toISOString();
const sevenDaysAgoIso = new Date(Date.now() - 7 * 86400000).toISOString();
const fourteenDaysAgoIso = new Date(Date.now() - 14 * 86400000).toISOString();
const thirtyDaysAgoIso = new Date(Date.now() - 30 * 86400000).toISOString();
const fourteenDaysAgoYmd = fourteenDaysAgoIso.slice(0, 10);

const [
  customers, bets, leadsRes, councilRes,
  hotLeads, openVis, staleTasks, recentTasks, recentLeads, recentVisActions,
  recentOverrides, unsuitableFlags,
  greenIdeas, focusHistory, closedBets
] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/customers?select=product,kind,mrr_usd,became_paid_at,churned_at&limit=500`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/bets?status=eq.live&select=hypothesis,kind,started_at,time_box_days,est_mrr_impact_usd&order=started_at.desc&limit=50`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/leads?status=in.(ready,contacted,conversation)&select=full_name,company,tier,follow_up_at&order=follow_up_at.asc.nullslast&limit=20`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/customers?kind=eq.paid&churned_at=is.null&select=full_name,email,product,mrr_usd,became_paid_at&order=mrr_usd.desc.nullslast&limit=10`, headers: hdr, json: true }),

  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/leads?status=in.(ready,conversation)&quality_score=eq.green&select=id,full_name,company,why_relevant,fit_score,follow_up_at&order=fit_score.desc.nullslast&limit=10`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/visibility_targets?status=neq.declined&deadline_at=gt.${nowIso}&select=id,title,type,deadline_at,relevance_score,quality_score&order=deadline_at.asc&limit=10`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/tasks?status=eq.waiting&krish_reviewed=eq.false&select=id,title,priority,lever_score,due_date,started_at&order=lever_score.desc.nullslast&limit=10`, headers: hdr, json: true }),

  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/tasks?status=eq.shipped&completed_at=gt.${sevenDaysAgoIso}&select=completed_at&limit=500`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/leads?created_at=gt.${sevenDaysAgoIso}&select=created_at&limit=500`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/visibility_targets?updated_at=gt.${sevenDaysAgoIso}&status=in.(accepted,submitted,pitched)&select=updated_at&limit=500`, headers: hdr, json: true }),

  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/feedback_queue?reason_code=eq.marcus_priority_override&created_at=gte.${thirtyDaysAgoIso}&select=created_at,reason_text,meta&order=created_at.desc&limit=80`, headers: hdr, json: true }).catch(() => []),

  // Pre-lock unsuitable flags: Krish thumbs-downs a Marcus pick before
  // calibrating, with a reason. Stronger negative signal than an override
  // (he never even considered locking it). Used to teach Marcus what NOT
  // to suggest.
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/feedback_queue?reason_code=eq.marcus_suggestion_unsuitable&created_at=gte.${thirtyDaysAgoIso}&select=created_at,reason_text,meta&order=created_at.desc&limit=80`, headers: hdr, json: true }).catch(() => []),

  // Synthesis context: green-quality content ideas that ladder into
  // distribution leverage. Cleo seeds these but Marcus doesn't see them yet.
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/content_ideas?state=in.(seeded,researching,drafting)&quality_score=eq.green&select=id,idea,thesis,distribution,state&limit=10`, headers: hdr, json: true }).catch(() => []),

  // Krish's locked daily_focus targets last 14 days — what is he actually
  // building toward? Used to detect strategic themes.
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/daily_focus?focus_date=gte.${fourteenDaysAgoYmd}&select=focus_date,target_1_text,target_2_text,target_3_text,status&order=focus_date.desc&limit=14`, headers: hdr, json: true }).catch(() => []),

  // Closed bets last 30d — momentum context (won, lost, est vs actual).
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/bets?status=in.(won,lost,killed)&select=hypothesis,kind,outcome,est_mrr_impact_usd,actual_mrr_impact_usd,closed_at&order=closed_at.desc&limit=20`, headers: hdr, json: true }).catch(() => []),
]);

const paidAddedYesterday = customers.filter(c => c.kind === 'paid'    && c.became_paid_at >= yesterdayIso);
const churnedYesterday   = customers.filter(c => c.kind === 'churned' && c.churned_at     >= yesterdayIso);
const yesterdayMrr = paidAddedYesterday.reduce((s, c) => s + (Number(c.mrr_usd) || 0), 0)
                   - churnedYesterday  .reduce((s, c) => s + (Number(c.mrr_usd) || 0), 0);

// Cohort rollups — cheap context for synthesis.
const paidLast30 = customers.filter(c => c.kind === 'paid'    && c.became_paid_at >= thirtyDaysAgoIso).length;
const churnLast30 = customers.filter(c => c.kind === 'churned' && c.churned_at     >= thirtyDaysAgoIso).length;
const totalPaid = customers.filter(c => c.kind === 'paid' && !c.churned_at).length;
const cohort = { paid_last_30d: paidLast30, churned_last_30d: churnLast30, total_paid: totalPaid };

const dayKey = (iso) => new Date(iso).toISOString().slice(0, 10);
const days = [];
for (let i = 6; i >= 0; i--) {
  days.push(new Date(Date.now() - i * 86400000).toISOString().slice(0, 10));
}
const bucket = (rows, key) => {
  const counts = days.map(() => 0);
  for (const r of rows || []) {
    const k = dayKey(r[key]);
    const idx = days.indexOf(k);
    if (idx >= 0) counts[idx] += 1;
  }
  return counts;
};
const mrrSeries = days.map(d => {
  const dayStart = d + 'T00:00:00Z', dayEnd = d + 'T23:59:59Z';
  const added   = customers.filter(c => c.kind === 'paid'    && c.became_paid_at >= dayStart && c.became_paid_at <= dayEnd);
  const churned = customers.filter(c => c.kind === 'churned' && c.churned_at     >= dayStart && c.churned_at     <= dayEnd);
  return added.reduce((s, c) => s + (Number(c.mrr_usd) || 0), 0)
       - churned.reduce((s, c) => s + (Number(c.mrr_usd) || 0), 0);
});
const momentum = {
  mrr:        mrrSeries,
  leads:      bucket(recentLeads,       'created_at'),
  shipped:    bucket(recentTasks,       'completed_at'),
  visibility: bucket(recentVisActions,  'updated_at'),
  days,
};

return [{
  json: {
    customers, bets, leads: leadsRes, council: councilRes,
    hot_leads: hotLeads, open_visibility: openVis, stale_tasks: staleTasks,
    yesterday_mrr_delta_usd: yesterdayMrr,
    momentum,
    overrides: Array.isArray(recentOverrides) ? recentOverrides : [],
    unsuitable: Array.isArray(unsuitableFlags) ? unsuitableFlags : [],
    green_ideas: Array.isArray(greenIdeas) ? greenIdeas : [],
    focus_history: Array.isArray(focusHistory) ? focusHistory : [],
    closed_bets: Array.isArray(closedBets) ? closedBets : [],
    cohort,
  },
}];

const response = $input.first().json;
const blocks = response.content || [];
const text = blocks.map(b => b.text || '').join('').trim();
let payload = null;
try {
  const a = text.indexOf('{'); const b = text.lastIndexOf('}');
  if (a >= 0 && b > a) payload = JSON.parse(text.slice(a, b + 1));
} catch { payload = null; }
const parsed = payload !== null;
payload = payload || {};

// Why the brief says so when it failed.
//
// This line used to be `payload.daily_brief || { body: text }`, which put the
// RAW MODEL TEXT into the brief body and said nothing. The top_three cards
// below already tag their fallbacks with reasoning, and FocusCalibrator
// renders that tag — but DailyBriefBanner renders the brief, and the brief
// carried no marker at all. So a morning where the brief failed looked exactly
// like a morning where Marcus had written one, which is the one thing a daily
// brief must never do: it is read first and trusted most.
//
// stop_reason is checked too. A brief cut off at max_tokens produces text that
// parses as prose and fails as JSON, and it is worth distinguishing "the model
// broke" from "the model ran out of room" when someone comes to fix it.
const truncated = response.stop_reason === 'max_tokens';
const brief = parsed && payload.daily_brief
  ? payload.daily_brief
  : {
      body: text,
      degraded: true,
      reasoning: truncated
        ? 'fallback — the brief hit the token ceiling mid-JSON, so this is the raw partial'
        : 'fallback — Marcus returned text that did not parse as a brief, shown raw',
    };
brief.yesterday_mrr_delta_usd = $('Pull live data').item.json.yesterday_mrr_delta_usd || 0;

const now = Date.now();
const expires = new Date(now + 24 * 3600 * 1000).toISOString();
const allowedKinds = new Set(['task','lead','guest','idea','visibility']);
function isCard(c) {
  return c && ['revenue','growth','risk'].includes(c.kind)
    && typeof c.title === 'string' && typeof c.why_now === 'string'
    && typeof c.action_label === 'string' && allowedKinds.has(c.action_kind);
}
function normalize(c) {
  return {
    kind: c.kind,
    title: c.title,
    why_now: c.why_now,
    action_label: c.action_label,
    action_kind: c.action_kind,
    action_target_id: c.action_target_id ?? '',
    expires_at: c.expires_at || expires,
    leverage_score: typeof c.leverage_score === 'number' ? c.leverage_score : null,
    reasoning: typeof c.reasoning === 'string' ? c.reasoning : null,
    beats: Array.isArray(c.beats) ? c.beats : undefined,
  };
}

function safeTopThree(raw, hot_leads, open_visibility, stale_tasks) {
  if (Array.isArray(raw) && raw.length === 3 && raw.every(isCard)) {
    return raw.map(normalize);
  }
  const lead = (hot_leads || [])[0];
  const vis  = (open_visibility || [])[0];
  const task = (stale_tasks || [])[0];
  const fb = (kind, title, why_now, action_label, action_kind, action_target_id) => normalize({
    kind, title, why_now, action_label, action_kind, action_target_id,
    leverage_score: 0, reasoning: 'fallback — Marcus brief failed, raw queue pick',
  });
  return [
    lead
      ? fb('revenue', `Open ${lead.full_name || 'lead'}${lead.company ? ' · ' + lead.company : ''}`, lead.why_relevant || 'Hot green-quality lead waiting for outreach.', 'Open lead', 'lead', lead.id)
      : fb('revenue', 'No green leads in queue', 'Felix has nothing live. Surface a customer call instead.', 'Open Today', 'task', ''),
    vis
      ? fb('growth', `${vis.title || 'Visibility target'}${vis.type ? ' (' + vis.type + ')' : ''}`, vis.deadline_at ? `Deadline ${new Date(vis.deadline_at).toISOString().slice(0,10)}` : 'Deadline approaching.', 'Open target', 'visibility', vis.id)
      : fb('growth', 'No active visibility targets', 'Nova is dry. Audit /visibility for revival candidates.', 'Open Visibility', 'visibility', ''),
    task
      ? fb('risk', task.title || 'Stale task', 'High-leverage and stalled. Triage or kill.', 'Triage task', 'task', task.id)
      : fb('risk', 'No stale risks', 'Inbox is clean. Spend the slack on customer calls.', 'Open Today', 'task', ''),
  ];
}

function safeAlternates(raw, hot_leads, open_visibility, stale_tasks, primaryIds) {
  if (Array.isArray(raw)) {
    const cleaned = raw.filter(isCard).slice(0, 4).map(normalize);
    // Trust Marcus — only fall back if he produced literally nothing.
    if (cleaned.length > 0) return cleaned;
  }
  // Fallback: 4 next-best rows across queues, badged so UI shows 'fallback'.
  const candidates = [];
  const used = new Set(primaryIds);
  for (const l of (hot_leads || []).slice(1, 5)) {
    if (l.id && !used.has(l.id)) {
      candidates.push({ kind: 'revenue', title: `Open ${l.full_name || 'lead'}${l.company ? ' · ' + l.company : ''}`, why_now: l.why_relevant || 'Next hot lead.', action_label: 'Open lead', action_kind: 'lead', action_target_id: l.id, leverage_score: 0, reasoning: 'fallback — Marcus alternates failed' });
      used.add(l.id);
    }
  }
  for (const v of (open_visibility || []).slice(1, 5)) {
    if (candidates.length >= 4) break;
    if (v.id && !used.has(v.id)) {
      candidates.push({ kind: 'growth', title: v.title || 'Visibility target', why_now: v.deadline_at ? `Deadline ${new Date(v.deadline_at).toISOString().slice(0,10)}` : 'Next open target.', action_label: 'Open target', action_kind: 'visibility', action_target_id: v.id, leverage_score: 0, reasoning: 'fallback — Marcus alternates failed' });
      used.add(v.id);
    }
  }
  for (const t of (stale_tasks || []).slice(1, 5)) {
    if (candidates.length >= 4) break;
    if (t.id && !used.has(t.id)) {
      candidates.push({ kind: 'risk', title: t.title || 'Stale task', why_now: 'Next high-leverage stalled task.', action_label: 'Triage task', action_kind: 'task', action_target_id: t.id, leverage_score: 0, reasoning: 'fallback — Marcus alternates failed' });
      used.add(t.id);
    }
  }
  return candidates.map(normalize);
}

const pull = $('Pull live data').item.json;
const top_three = safeTopThree(payload.top_three, pull.hot_leads, pull.open_visibility, pull.stale_tasks);
const primaryIds = top_three.map(c => c.action_target_id).filter(Boolean);
const top_three_alternates = safeAlternates(payload.top_three_alternates, pull.hot_leads, pull.open_visibility, pull.stale_tasks, primaryIds);
const top_three_reasoning = typeof payload.top_three_reasoning === 'string'
  ? payload.top_three_reasoning.slice(0, 400)
  : null;
const momentum = pull.momentum;

return [{ json: {
  brief, top_three, top_three_alternates, top_three_reasoning, momentum,
  telegram_text: 'Today: ' + (brief.one_bet || brief.body || 'No brief.')
    + (brief.one_customer    ? '\nTalk to: ' + brief.one_customer       : '')
    + (brief.one_anti_action ? '\nDon\'t: ' + brief.one_anti_action     : '')
    + (brief.yesterday_mrr_delta_usd ? '\nYesterday: $' + Math.round(brief.yesterday_mrr_delta_usd) + ' MRR' : '')
} }];
